<?php
session_start(); require_once __DIR__.'/config/db.php';
function ht($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=(int)($_GET['id']??$_POST['test_id']??0); if(!$pdo||$id<1){http_response_code(404);die('Test topilmadi.');}
$q=$pdo->prepare('SELECT * FROM online_tests WHERE id=? AND is_active=1');$q->execute([$id]);$test=$q->fetch();if(!$test)die('Test mavjud emas yoki faol emas.');
$q=$pdo->prepare('SELECT id,question_text,option_a,option_b,option_c,option_d FROM test_questions WHERE test_id=? ORDER BY sort_order,id');$q->execute([$id]);$questions=$q->fetchAll();if(!$questions)die('Bu testda savollar hali kiritilmagan.');
$result=null;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$answers=$_POST['answers']??[];
 if($name===''||$phone===''||!is_array($answers))$error='Ism va telefonni to‘ldiring.';
 else {$correct=0;$clean=[];$answerQ=$pdo->prepare('SELECT id,correct_option FROM test_questions WHERE test_id=?');$answerQ->execute([$id]);$keys=$answerQ->fetchAll();$keyMap=[];foreach($keys as $k)$keyMap[$k['id']]=$k['correct_option'];foreach($questions as $question){$a=strtoupper((string)($answers[$question['id']]??''));if(!in_array($a,['A','B','C','D'],true))$a='';$clean[$question['id']]=$a;if($a!==''&&isset($keyMap[$question['id']])&&$a===$keyMap[$question['id']])$correct++;}$total=count($questions);$percent=round($correct/$total*100,2);$ins=$pdo->prepare('INSERT INTO test_results(test_id,full_name,phone,total_questions,correct_answers,percentage,answers_json) VALUES(?,?,?,?,?,?,?)');$ins->execute([$id,$name,$phone,$total,$correct,$percent,json_encode($clean,JSON_UNESCAPED_UNICODE)]);$result=['correct'=>$correct,'total'=>$total,'percent'=>$percent];}
}
?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ht($test['title'])?> — Algoritm</title><link rel="stylesheet" href="assets/css/style.css?v=8"><style>.quiz{max-width:850px;margin:45px auto;padding:20px}.quiz-box{background:#121216;border:1px solid #342027;border-radius:18px;padding:24px;margin:18px 0}.quiz label{display:block;background:#1b1b21;border:1px solid #303039;padding:12px;border-radius:10px;margin:8px 0;cursor:pointer}.quiz input[type=radio]{accent-color:#e50914;margin-right:8px}.quiz input[type=text],.quiz input[type=tel]{width:100%;padding:13px;border-radius:9px;background:#08080a;border:1px solid #38383f;color:#fff;margin:7px 0 12px}.result{padding:25px;border-radius:16px;background:#17171c;border:1px solid #e50914;margin:20px 0}.score{font-size:34px;font-weight:800;color:#ff3144}</style></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">A</span><span>ALGORITM<small>Online test</small></span></a><nav><a href="tests.php">Testlar</a><a href="index.php">Bosh sahifa</a></nav></header><main class="quiz"><span class="eyebrow">ONLINE TEST</span><h1><?=ht($test['title'])?></h1><p><?=ht($test['description']??'')?></p><?php if($result): ?><div class="result"><div class="score"><?=$result['correct']?> / <?=$result['total']?> (<?=$result['percent']?>%)</div><p>Test yakunlandi. Natijangiz saqlandi.</p><a class="button primary" href="tests.php">Boshqa testni tanlash</a></div><?php else: ?><?php if($error): ?><div class="alert error"><?=ht($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="test_id" value="<?=$id?>"><section class="quiz-box"><h2>O‘quvchi ma’lumotlari</h2><label for="nm">Ism va familiya</label><input id="nm" name="full_name" required maxlength="120" value="<?=ht($_POST['full_name']??'')?>"><label for="ph">Telefon raqami</label><input id="ph" name="phone" type="tel" required maxlength="25" value="<?=ht($_POST['phone']??'')?>"></section><?php foreach($questions as $i=>$question): ?><section class="quiz-box"><h3><?=($i+1)?>. <?=ht($question['question_text'])?></h3><?php foreach(['A'=>'option_a','B'=>'option_b','C'=>'option_c','D'=>'option_d'] as $letter=>$field): ?><label><input type="radio" name="answers[<?=$question['id']?>]" value="<?=$letter?>" <?=((($_POST['answers'][$question['id']]??'')===$letter)?'checked':'')?>> <strong><?=$letter?>.</strong> <?=ht($question[$field])?></label><?php endforeach; ?></section><?php endforeach; ?><button class="button primary" type="submit">Testni yakunlash →</button></form><?php endif; ?></main><script src="assets/js/theme.js?v=8"></script></body></html>
